<script setup>
import { photos, projects, media, packages, testimonials } from '../data.js'
import { motion } from 'motion-v'
import { readArray } from '../storage.js'
import LandingHero from '../components/LandingHero.vue'
import { ref } from 'vue'; import Gallery from '../components/Gallery.vue'; import PhotoViewer from '../components/PhotoViewer.vue'
const favoriteIds=ref(readArray('casil-favorites')); const active=ref(null)
function favorite(p){favoriteIds.value=favoriteIds.value.includes(p.id)?favoriteIds.value.filter(x=>x!==p.id):[...favoriteIds.value,p.id];localStorage.setItem('casil-favorites',JSON.stringify(favoriteIds.value))}
const open=(p)=>active.value=p; const move=(step)=>{let i=photos.findIndex(p=>p.id===active.value.id);active.value=photos[(i+step+photos.length)%photos.length]}
</script>
<template><LandingHero/><section class="section"><div class="section-head"><div><span class="eyebrow">Selected frames</span><h2>Stories, still unfolding.</h2></div><RouterLink class="text-link" to="/portfolio">View full portfolio  -> </RouterLink></div><Gallery :photos="photos.slice(0,6)" :filter="false" :favorites="favoriteIds" @favorite="favorite" @open="open"/></section><section class="section about-band"><div><span class="eyebrow">Behind the camera</span><h2>Made of moments.<br/>Kept in photographs.</h2><p class="muted">Casil Shots creates thoughtful images for people and milestones that matter. Every session is shaped around real connection, considered light and the small details that make a story yours.</p><RouterLink to="/about" class="text-link">Meet Casil Shots  -> </RouterLink></div><img :src="photos[7].image" alt="Portrait in natural light" loading="lazy"/></section><section class="section"><div class="section-head"><div><span class="eyebrow">Featured films</span><h2>In motion.</h2></div><RouterLink to="/media" class="text-link">All six films  -> </RouterLink></div><div class="cards"><article v-for="film in media" :key="film.id" class="card media-card-wrap"><div class="media-card"><img :src="film.thumbnail" :alt="film.title" loading="lazy"/><button class="play" :aria-label="`Play ${film.title}`" @click="$router.push('/media')">PLAY</button></div><div class="media-info"><small>{{film.category}}  |  {{film.duration}}</small><h3>{{film.title}}</h3></div></article></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">The experience</span><h2>Made for your story.</h2></div><RouterLink to="/services" class="text-link">Explore services  -> </RouterLink></div><div class="cards"><article v-for="s in packages" :key="s.name" class="card"><span class="eyebrow">{{s.coverage}}</span><h3>{{s.name}} · {{s.price}}</h3><p>{{s.description}}</p><RouterLink class="text-link" :to="`/contact?package=${encodeURIComponent(s.name)}`">Inquire  -> </RouterLink></article></div><p class="notice">Package details and availability are confirmed when you inquire.</p></section><section class="section testimonials"><span class="eyebrow">Kind words  |  sample testimonials</span><div class="cards"><blockquote v-for="t in testimonials" :key="t.name" class="card"><h3>{{t.quote}}</h3><p>{{t.name}}</p></blockquote></div></section><section class="section cta-band"><span class="eyebrow">Your story, next</span><h2>Let's make something<br/><em>worth keeping.</em></h2><RouterLink class="button" to="/contact">Start an inquiry</RouterLink></section><PhotoViewer :photo="active" @close="active=null" @move="move"/></template>
